// Cards that lift on hover with a plain CSS transition whose easing is a spring generated by spring()
import { delay, hover, scopeMotion, spring } from 'motion';
import type { Mount } from '@/types.ts';
import { hint, panel } from '../../shared/ui.ts';
import './style.css';

interface Preset {
  name: string;
  visualDuration: number;
  bounce: number;
  hue: number;
}
const PRESETS: Preset[] = [
  { name: 'Crisp', visualDuration: 0.25, bounce: 0, hue: 205 },
  { name: 'Springy', visualDuration: 0.5, bounce: 0.2, hue: 160 },
  { name: 'Bouncy', visualDuration: 0.6, bounce: 0.5, hue: 330 },
];

const mount: Mount = (el, { preview }) => {
  const custom: Preset = { name: 'Custom', visualDuration: 0.4, bounce: 0.35, hue: 40 };
  const presets = preview ? PRESETS : [...PRESETS, custom];

  el.innerHTML = '<div class="row"></div><code class="css"></code>';
  const row = el.querySelector<HTMLElement>('.row')!;
  row.classList.toggle('full', !preview);
  const out = el.querySelector<HTMLElement>('.css')!;
  const tiles = presets.map((p) => {
    const tile = document.createElement('div');
    tile.className = 'tile';
    tile.tabIndex = 0;
    tile.style.setProperty('--hue', String(p.hue));
    tile.innerHTML = '<span class="dot"></span><b></b><small></small>';
    tile.querySelector('b')!.textContent = p.name;
    row.append(tile);
    return tile;
  });

  // The transition is set from JS before the transform changes, as css.md's "style attribute" section does.
  // spring(visualDuration, bounce) stringifies to e.g. "800ms linear(0, 0.01, ...)".
  const apply = (tile: HTMLElement, p: Preset): string => {
    const css = `transform ${spring(p.visualDuration, p.bounce)}`;
    tile.style.transition = css;
    tile.querySelector('small')!.textContent = `${p.visualDuration}s, bounce ${p.bounce}`;
    return css;
  };
  const show = (css: string): void => {
    // The whole string is long (a linear() curve with dozens of points): show its head and its size.
    out.textContent = `transition: ${css.length > 52 ? css.slice(0, 52) + '…' : css}  [${css.length} chars]`;
  };

  const scope = scopeMotion(el, () => {
    tiles.forEach((tile, i) => {
      const p = presets[i]!;
      show(apply(tile, p));
      // hover() ignores the fake hover events touch screens emit.
      hover(tile, () => {
        show(apply(tile, p));
        tile.style.transform = 'translateY(-14px) scale(1.08)';
        return () => {
          tile.style.transform = '';
        };
      });
    });

    if (preview) {
      // No pointer in a card: set the same transforms on a timer, one tile at a time.
      let i = 0;
      const tick = (): void => {
        const tile = tiles[i % tiles.length]!;
        show(apply(tile, presets[i % tiles.length]!));
        tile.style.transform = 'translateY(-14px) scale(1.08)';
        delay(() => (tile.style.transform = ''), 0.9);
        i++;
        delay(tick, 1.4);
      };
      delay(tick, 0.5);
    }
  });

  let ui: ReturnType<typeof panel> | undefined;
  if (!preview) {
    ui = panel(el);
    ui.slider('Custom: visual duration', { min: 0.1, max: 1.5, step: 0.05, value: custom.visualDuration }, (v) => {
      custom.visualDuration = v;
      show(apply(tiles[3]!, custom));
    });
    ui.slider('bounce', { min: 0, max: 0.9, step: 0.05, value: custom.bounce }, (v) => {
      custom.bounce = v;
      show(apply(tiles[3]!, custom));
    });
    hint(el, 'Hover a card. The lift is a plain CSS transition; only its timing string comes from spring(). Edit the Custom card to see the string change.');
  }

  return () => {
    scope.cancel();
    ui?.dispose();
  };
};

export default mount;
